import { SensorViewer,colors,parts } from './viewer3d.js';

const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)];
// 웹 데모(GitHub Pages)에서는 서비스 워커가 app-base·app-demo 표시를 넣어 준다. 서버로 실행하면 둘 다 없다.
const BASE=($('meta[name="app-base"]')?.content||'').replace(/\/$/,''),DEMO=!!$('meta[name="app-demo"]');
const appPath=(p=location.pathname)=>BASE&&(p===BASE||p.startsWith(BASE+'/'))?p.slice(BASE.length)||'/':p;
const DEMO_ACCOUNTS=[['field','field1234','현장 사용자'],['admin','admin1234','관리자'],['sysadmin','sys1234','시스템 관리자']];
if(BASE){const fix=n=>{if(n.nodeType!==1)return;const q='a[href^="/"]:not([data-external])';for(const a of [...(n.matches(q)?[n]:[]),...n.querySelectorAll(q)]){const h=a.getAttribute('href');if(!h.startsWith(BASE+'/'))a.setAttribute('href',BASE+h);}};new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(fix))).observe(document.documentElement,{childList:true,subtree:true});}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={SCRATCH:'기스 · 긁힘',DENT:'찍힘',CRACK:'크랙',CHIP:'깨짐 · 결손',COATING:'코팅 손상 · 오염',DEFORM:'변형',ETC:'기타'};
const states={SUBMITTED:'검토 대기',IN_REVIEW:'검토 중',NEED_INFO:'보완 요청',APPROVED:'승인 완료',REJECTED:'반려',ACTIVE:'현존',REPAIRED:'수리 완료',CLOSED:'종료'};
const events={CONFIRMED:'파손 확인',CHANGED:'파손 변화',CORRECTED:'내용 정정',MERGED:'기존 파손 재확인',REPAIRED:'수리 완료',CLOSED:'파손 종료',INSPECTED:'점검 완료 · 신규 파손 없음',MOUNTED:'센서 장착',UNMOUNTED:'센서 탈착'};
const roles={FIELD:'현장 사용자',ADMIN:'관리자',SYSADMIN:'시스템 관리자'};
const slotNames={LIDAR_1:'라이다 #1',LIDAR_2:'라이다 #2',CAM_1:'카메라 #1',CAM_2:'카메라 #2'};
const dateNow=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date());
const fmt=v=>v?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',...(v.includes('T')?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(v)):'기록 없음';
const icons={robot:'M5 8h14v12H5z M9 8V4m6 4V4 M9 12h.01M15 12h.01 M9 16h6 M2 11v6m20-6v6',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6m-6 4h6',check:'M4 12l5 5L20 6',review:'M9 3H5v18h14V3h-4 M9 2h6v4H9z M8 13l3 3 5-6',tool:'M14 6a5 5 0 0 0-6 6L3 17a3 3 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-4 4-4-4z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 3a4 4 0 0 1 0 8m0 4a4 4 0 0 1 4 4v2',search:'M20 20l-5-5 M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',clock:'M12 8v5l3 2 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',box:'M3 7l9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5m-9 5v10',logout:'M10 3H4v18h6 M9 12h12m-4-4 4 4-4 4',close:'M6 6l12 12M6 18 18 6',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2',qr:'M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h-2zm4 4h2v2h-2zM15 21v-2m6-4h-2',sensor:'M5 8c0-6 14-6 14 0v9c0 6-14 6-14 0z M5 8c0 6 14 6 14 0 M5 13c0 6 14 6 14 0',camera:'M3 7h18v13H3zM8 7l2-4h4l2 4 M12 10a3 3 0 1 0 0 6 3 3 0 0 0 0-6',download:'M12 3v12m-5-5 5 5 5-5 M4 16v5h16v-5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const brand=()=>`<div class="brand"><span class="brand-icon">${icon('robot')}</span><div><strong>센서로그</strong><small>ROBOT SENSOR ARCHIVE</small></div></div>`;
function art(model='robot'){
 if(model==='robot')return `<svg viewBox="0 0 220 135" aria-hidden="true"><ellipse cx="110" cy="113" rx="74" ry="10" fill="#dae4db"/><path d="M37 66 113 41 187 64 111 94z" fill="#d0dcd0"/><path d="M37 66v29l74 24V94z" fill="#91a892"/><path d="M111 94v25l76-24V64z" fill="#b4c6b2"/><path d="M54 64v-9l58-19 56 17v10l-57 18z" fill="#e6ece1"/><path d="M65 55v-9l47-16 45 15v9l-45 14z" fill="#d9e5d7"/><ellipse cx="110" cy="33" rx="19" ry="7" fill="#e5ede1"/><path d="M91 32v12c0 8 38 8 38-1V32" fill="#527661"/><ellipse cx="110" cy="32" rx="19" ry="7" fill="#779b81"/><path d="M53 84v14l13 4V88zm95 12v14l15-5V90z" fill="#415749"/><path d="M83 79v7l15 5v-7z" fill="#547262"/><circle cx="87" cy="84" r="2" fill="#c8d9cc"/><circle cx="94" cy="87" r="2" fill="#c8d9cc"/><path d="M127 81l42-14" stroke="#729179" stroke-width="2"/></svg>`;
 if(model==='CAMERA')return `<svg viewBox="0 0 180 110" aria-hidden="true"><ellipse cx="90" cy="94" rx="58" ry="8" fill="#dbe4db"/><path d="M35 27 120 18 146 35v51l-88 12-23-16z" fill="#b9c7bb"/><path d="M35 27 120 18 146 35 59 47z" fill="#e0e7dc"/><path d="M59 47 146 35v51l-87 12z" fill="#344e43"/><ellipse cx="81" cy="70" rx="13" ry="15" fill="#1d322b"/><ellipse cx="81" cy="70" rx="9" ry="11" fill="#547c73"/><ellipse cx="123" cy="63" rx="13" ry="15" fill="#1d322b"/><ellipse cx="123" cy="63" rx="9" ry="11" fill="#547c73"/><path d="M38 40v37" stroke="#93a798" stroke-width="2"/></svg>`;
 return model==='DOME'?`<svg viewBox="0 0 180 110" aria-hidden="true"><ellipse cx="90" cy="95" rx="49" ry="8" fill="#dce5dc"/><path d="M42 64 88 48 139 65v24l-48 17-49-19z" fill="#b0c3b5"/><path d="M91 80 139 65v24l-48 17z" fill="#859d8c"/><path d="M46 63a44 44 0 0 1 88 0c0 25-88 25-88 0" fill="#2f5147"/><path d="M57 48c7-26 39-34 56-13" fill="none" stroke="#648478" stroke-width="4"/><ellipse cx="90" cy="64" rx="44" ry="14" fill="#3b6254"/><path d="M52 72q37 16 76-1" fill="none" stroke="#173f32" stroke-width="4"/></svg>`:`<svg viewBox="0 0 180 110" aria-hidden="true"><ellipse cx="90" cy="97" rx="47" ry="8" fill="#dce5dc"/><path d="M45 28v58c0 24 90 24 90 0V28" fill="#b2c6b7"/><path d="M45 40v28c0 24 90 24 90 0V40" fill="#33594a"/><ellipse cx="90" cy="29" rx="45" ry="16" fill="#dce5da"/><ellipse cx="90" cy="29" rx="35" ry="10" fill="#c7d5c5"/><path d="M52 49v16m7-14v17m7-14v16m7-14v16" stroke="#5a7a66" stroke-width="2"/></svg>`;
}
let user=null,csrf='',summary={},viewer=null,current=null,routeGeneration=0,pollTimer;
const isAdmin=()=>user&&user.role!=='FIELD';
async function api(url,{method='GET',body}={}){const headers={};if(method!=='GET')headers['X-CSRF-Token']=csrf;if(body&&!(body instanceof FormData))headers['Content-Type']='application/json';const r=await fetch('/api'+url,{method,headers,body:body instanceof FormData?body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok){if(r.status===401&&user){user=null;go('/login');}throw new Error(d.error||'요청에 실패했습니다.');}return d;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function badge(status){return `<span class="badge ${status==='ACTIVE'||status==='APPROVED'?'green':status==='REJECTED'?'red':status==='NEED_INFO'||status==='SUBMITTED'?'amber':'blue'}">${esc(states[status]||status)}</span>`;}
function empty(message,ic='box'){return `<div class="empty">${icon(ic)}${message}</div>`;}
function options(obj,selected){return Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${k===selected?'selected':''}>${esc(v)}</option>`).join('');}
function bindForm(form,fn){form.addEventListener('submit',async e=>{e.preventDefault();$('.form-error',form)?.remove();const btn=$('button[type=submit]',form);if(btn)btn.disabled=true;try{await fn(new FormData(form),form);}catch(err){const div=document.createElement('div');div.className='form-error';div.textContent=err.message;form.prepend(div);}finally{if(btn)btn.disabled=false;}});}
function modal(title,html,onSubmit){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="ghost" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!el.open)el.showModal();if(onSubmit)bindForm($('form',el),async(f,form)=>{await onSubmit(f,form);el.close();});}
function go(path,replace=false){history[replace?'replaceState':'pushState']({},'',BASE+appPath(path));render();}
function demoBanner(){return DEMO?`<div class="demo-banner" role="note"><strong>웹 데모</strong><span>설치 없이 이 브라우저 안에서 실행 중입니다. 데이터는 이 브라우저에만 저장됩니다.</span><button class="small" data-action="demo-reset">데모 초기화</button><a class="small" href="${esc(new URL('../',location.origin+BASE+'/').pathname)}" data-external>홈페이지</a></div>`:'';}
function shell(title,body){const path=appPath();$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<nav><div class="nav-label">WORKSPACE</div><a href="/" class="nav-item ${path==='/'||path.startsWith('/robot/')?'active':''}">${icon('grid')}<span class="nav-text">호기 현황</span></a><a href="/my-reports" class="nav-item ${path==='/my-reports'?'active':''}">${icon('file')}<span class="nav-text">내 신고</span></a>${isAdmin()?`<div class="nav-label">MANAGEMENT</div><a href="/admin/reports" class="nav-item ${path==='/admin/reports'?'active':''}">${icon('review')}<span class="nav-text">신고 검토</span><span class="badge amber" data-pending>${summary.pending||0}</span></a><a href="/admin/robots" class="nav-item ${path==='/admin/robots'?'active':''}">${icon('tool')}<span class="nav-text">호기 · 센서</span></a>`:''}${user.role==='SYSADMIN'?`<a href="/admin/users" class="nav-item ${path==='/admin/users'?'active':''}">${icon('users')}<span class="nav-text">계정 관리</span></a>`:''}</nav><div class="sidebar-bottom"><div class="storage-status"><span class="dot"></span>${DEMO?'웹 데모 · 이 브라우저에 저장':'로컬 서버 · 기록 저장 중'}</div><div class="profile"><span class="avatar">${esc(user.name[0])}</span><div><strong>${esc(user.name)}</strong><small>${roles[user.role]}</small></div><button class="ghost" data-action="logout" title="로그아웃">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><a href="/">워크스페이스</a><span>/</span><strong>${esc(title)}</strong></div><div class="topbar-right"><span>${dateNow().replaceAll('-','. ')} · 센서 이력관리</span><button class="ghost small" data-action="password" title="비밀번호 변경">${icon('users')}</button><a href="${isAdmin()?'/admin/reports':'/my-reports'}" title="신고 알림">${icon('bell')}</a><button class="ghost small" data-action="logout" aria-label="로그아웃">${icon('logout')}</button></div></header><div class="content">${demoBanner()}${body}</div></main></div>`;}
function head(kicker,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow" style="margin-bottom:10px">${esc(kicker)}</div><h1>${esc(title)}</h1><p class="subtitle">${esc(description)}</p></div><div class="row">${actions}</div></div>`;}
async function render(){const gen=++routeGeneration;if(viewer){viewer.dispose();viewer=null;}current=null;try{
 if(!user){try{const a=await api('/auth/me');user=a.user;csrf=a.csrf;}catch{login();return;}}
 if(user.must_change){passwordPage();return;}
 summary=await api('/summary');if(gen!==routeGeneration)return;
 const path=appPath();
 if(path==='/login'){go('/',true);return;}
 if(path.startsWith('/admin/')&&!isAdmin()){go('/',true);return;}
 if(path==='/admin/users'&&user.role!=='SYSADMIN'){go('/',true);return;}
 if(path==='/'){await home(gen);}else if(/^\/robot\/\d+\/[A-Z0-9_]+$/.test(path)){await sensorPage(gen);}else if(/^\/robot\/\d+$/.test(path)){await robotPage(gen);}else if(path==='/my-reports'){await reportsPage(false,gen);}else if(path==='/admin/reports'){await reportsPage(true,gen);}else if(path==='/admin/robots'){await managePage(gen);}else if(path==='/admin/users'){await usersPage(gen);}else{go('/',true);}
 }catch(e){if(gen===routeGeneration){shell('오류',head('ERROR','화면을 불러오지 못했습니다',e.message,'<button data-action="reload">다시 시도</button>'));}}}
function login(){if(viewer)viewer.dispose();viewer=null;$('#app').innerHTML=`<div class="login"><section class="login-art">${brand()}<h1>작은 흔적도,<br>놓치지 않는 기록.</h1><p>센서의 오늘을 확인하고, 어제의 이력을 연결합니다.<br>로봇 센서 파손을 3D로 보고 함께 관리하세요.</p><div class="login-graphic">${art('robot')}</div><div class="eyebrow">TRACE EVERY DETAIL. KEEP EVERY HISTORY.</div></section><section class="login-form"><div class="login-box"><div class="eyebrow">SENSORLOG WORKSPACE</div><h2>워크스페이스 로그인</h2><p class="subtitle">발급받은 계정으로 접속하세요.</p><form id="login-form"><label>아이디<input name="username" autocomplete="username" placeholder="아이디를 입력하세요" required></label><label>비밀번호<input name="password" type="password" autocomplete="current-password" placeholder="비밀번호를 입력하세요" required></label><label class="check"><input name="remember" type="checkbox" checked>이 기기에서 30일간 로그인 유지</label><button type="submit" class="primary">로그인 ${icon('arrow')}</button></form>${DEMO?`<div class="demo-accounts"><div class="eyebrow">웹 데모 계정 · 눌러서 바로 로그인</div>${DEMO_ACCOUNTS.map(([u,p,label])=>`<button type="button" data-action="demo-login" data-u="${u}" data-p="${p}"><strong>${label}</strong><span class="mono">${u} / ${p}</span></button>`).join('')}<p>데이터는 이 브라우저에만 저장됩니다. 실제 운영은 내 PC·서버에서 실행하세요.</p></div>`:`<div class="login-footer">최초 실행 시 <span class="mono">data/initial-account.txt</span>에서 초기 계정을 확인하세요.<br>처음 로그인하면 비밀번호를 변경합니다.</div>`}</div></section></div>`;bindForm($('#login-form'),async f=>{const a=await api('/auth/login',{method:'POST',body:{username:f.get('username'),password:f.get('password'),remember:!!f.get('remember')}});user=a.user;csrf=a.csrf;render();});}
function passwordFields(){return `<label>현재 비밀번호<input type="password" name="current" required autocomplete="current-password"></label><label>새 비밀번호 · 12자 이상<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><label>새 비밀번호 확인<input type="password" name="confirm" minlength="12" required autocomplete="new-password"></label><button class="primary" type="submit">비밀번호 변경</button>`;}
async function changePassword(f){if(f.get('password')!==f.get('confirm'))throw new Error('새 비밀번호가 일치하지 않습니다.');await api('/auth/password',{method:'POST',body:Object.fromEntries(f)});user.must_change=false;toast('비밀번호를 변경했습니다.');go('/');}
function passwordPage(){ $('#app').innerHTML=`<div class="login-form" style="min-height:100vh"><div class="login-box">${brand()}<h2>새 비밀번호 설정</h2><p class="subtitle">첫 로그인입니다. 개인 비밀번호를 설정하세요.</p><form id="password-form">${passwordFields()}</form></div></div>`;bindForm($('#password-form'),changePassword);}
async function home(gen){const params=new URLSearchParams(location.search),status=params.get('status')||'ACTIVE',q=params.get('q')||'';const robots=await api(`/robots?status=${status}&q=${encodeURIComponent(q)}`);if(gen!==routeGeneration)return;current={robots};
 shell('호기 현황',head('FLEET OVERVIEW','로봇 센서 현황','호기를 선택해 센서 상태와 파손 이력을 확인하세요.',`${isAdmin()?'<button data-action="add-robot" class="primary">'+icon('plus')+'호기 등록</button>':''}`)+`<div class="stats">${[['운영 중인 로봇',summary.active,'대','현재 관리 중인 운영 호기','robot'],['현존 파손',summary.damages,'건','승인된 파손 · 수리 완료 제외','sensor'],[isAdmin()?'검토 대기':'진행 중인 내 신고',summary.pending,'건',isAdmin()?'접수 및 검토 중인 신고':'신고 결과는 내 신고에서 확인','review'],['폐기된 로봇',summary.disposed,'대','폐기 후에도 이력은 보존됩니다','box']].map(([label,n,unit,desc,ic])=>`<div class="stat card"><span class="stat-icon">${icon(ic)}</span><div class="stat-label">${label}</div><div class="stat-value">${n}<small>${unit}</small></div><div class="stat-caption">${desc}</div></div>`).join('')}</div><div class="section-title"><div class="row"><h2>호기 목록</h2><span class="badge">${robots.length}</span></div><span class="kicker">라이다 2개 · 카메라 2개 / 호기</span></div><div class="toolbar card"><form class="search" id="search-form">${icon('search')}<input name="q" value="${esc(q)}" placeholder="호기번호 검색 (예: 18)" aria-label="호기번호 검색" list="robot-numbers"><datalist id="robot-numbers">${robots.map(r=>`<option value="${r.no}">${r.no}호기</option>`).join('')}</datalist></form><div class="segmented">${[['ACTIVE','운영'],['DISPOSED','폐기'],['ALL','전체']].map(([s,n])=>`<button data-action="filter-status" data-status="${s}" class="${status===s?'active':''}">${n}</button>`).join('')}</div></div><div class="robot-grid">${robots.map(r=>`<button class="card robot-card" data-go="/robot/${r.no}"><div class="row between"><div class="robot-title">${String(r.no).padStart(2,'0')}<small>호기</small></div><span class="badge ${r.status==='ACTIVE'?'green':''}"><span class="dot"></span>${r.status==='ACTIVE'?'운영 중':'폐기'}</span></div><div class="robot-art">${art()}</div><div class="robot-meta">${r.shape==='DOME'?'반구형 · Mid-360':'원통형 라이다'} / D405</div><div class="row between robot-bottom"><span class="${r.damage_count?'count-damage':''}">${r.damage_count?'현존 파손 '+r.damage_count+'건':'등록 파손 없음'}</span>${icon('arrow')}</div></button>`).join('')}</div>${robots.length?'':empty('검색 조건에 맞는 호기가 없습니다.','search')}<div class="footer-note"><span>센서 시리얼과 장착 위치는 실물 확인 후 등록하세요.</span><span>SENSORLOG · 1.0</span></div>`);
 bindForm($('#search-form'),f=>{go('/?status='+status+'&q='+encodeURIComponent(f.get('q')));});let timer;$('#search-form input').addEventListener('input',e=>{clearTimeout(timer);const v=e.target.value;timer=setTimeout(()=>{go('/?status='+status+'&q='+encodeURIComponent(v));},600);});
}
async function robotPage(gen){const no=appPath().split('/')[2],r=await api('/robots/'+no);if(gen!==routeGeneration)return;current={robot:r};shell(`${no}호기`,head('ROBOT DETAIL',`${String(no).padStart(2,'0')}호기`,`${r.site} · ${r.status==='ACTIVE'?'운영 중':'폐기'} · ${r.shape==='DOME'?'반구형 라이다':'원통형 라이다'}`,`<button data-action="qr" data-no="${no}">${icon('qr')}QR 코드</button>${isAdmin()?`<button data-action="edit-robot" data-no="${no}">${icon('tool')}호기 설정</button>`:''}`)+`<div class="robot-overview card"><div class="overview-art">${art()}</div><div class="overview-info"><div class="row"><h2>센서 구성</h2><span class="badge">4개 슬롯</span></div><p class="subtitle">센서를 선택하면 3D 화면에서 파손 위치와 이력을 볼 수 있습니다.</p><div class="notice">장착 위치는 확인된 값만 표시합니다. ‘미확인’ 센서는 관리 화면에서 실물 시리얼과 위치를 등록하세요.</div></div></div><div class="sensor-grid">${Object.entries(slotNames).map(([slot,label])=>{const s=r.sensors.find(x=>x.slot===slot);return s?`<button class="card sensor-card" data-go="/robot/${no}/${slot}"><div class="row between"><h3>${label}</h3><span class="badge">${esc(s.position)}</span></div><div class="sensor-picture">${art(s.model)}</div><p class="serial">${s.verified?esc(s.serial):'시리얼 미확인 · 임시 센서 ID '+s.id}</p><div class="row between" style="margin-top:16px"><span class="badge ${s.damage_count?'amber':'green'}">${s.damage_count?'현존 파손 '+s.damage_count+'건':'등록 파손 없음'}</span><span class="kicker">대기 ${s.pending}건 ${icon('arrow')}</span></div><p class="serial" style="margin-top:13px">마지막 변경 ${fmt(s.last_changed)}</p></button>`:`<div class="card sensor-card"><h3>${label}</h3>${empty(r.status==='DISPOSED'?'폐기 호기 · 센서 이력은 관리 화면에서 조회':'장착된 센서가 없습니다.')}${isAdmin()&&r.status==='ACTIVE'?`<button data-action="mount" data-no="${no}" data-slot="${slot}">센서 장착</button>`:''}</div>`;}).join('')}</div>`);}
function controls(){return `<div class="view-controls">${[['reset','처음으로'],['front','정면'],['side','측면'],['top','상단'],['back','후면']].map(([v,t])=>`<button data-action="view" data-view="${v}">${t}</button>`).join('')}</div>`;}
function initViewer(el,s,opts){try{return new SensorViewer(el,s,opts);}catch(e){el.innerHTML=empty('이 기기에서 3D 가속을 사용할 수 없습니다.<br>브라우저의 하드웨어 가속을 켜고 다시 시도하세요.');toast('3D 초기화 실패: '+e.message);return null;}}
async function sensorPage(gen){const[, ,no,slot]=appPath().split('/');const r=await api('/robots/'+no),s=r.sensors.find(s=>s.slot===slot);if(!s)throw new Error('현재 슬롯에 장착된 센서가 없습니다.');const params=new URLSearchParams(location.search),at=params.get('at')||'',status=params.get('status')||'ACTIVE';const[damages,history]=await Promise.all([api(`/sensors/${s.id}/damages?status=${status}${at?'&at='+at:''}`),api(`/sensors/${s.id}/history`)]);if(gen!==routeGeneration)return;
 current={robot:r,sensor:s,damages,history,at,selected:params.get('damage'),points:[],normal:[0,1,0],part:'',reporting:false};
 shell(`${no}호기 / ${slotNames[slot]}`,head('SENSOR WORKSPACE',`${String(no).padStart(2,'0')}호기 · ${slotNames[slot]}`,`${s.label} · ${s.verified?s.serial:'실물 시리얼 미확인'} · 장착 위치 ${s.position}`,`<button data-action="share">${icon('link')}공유</button><button data-action="inspect">${icon('check')}점검 완료</button><button class="primary desktop-report" data-action="start-report">${icon('plus')}파손 신고</button>`)+`<div class="viewer-layout"><div><section class="card viewer-card"><div class="viewer-top"><div class="row">${icon('sensor')}<h3>${s.model==='DOME'?'Livox Mid-360':s.model==='CAMERA'?'RealSense D405':'원통형 라이다'}</h3></div><span class="badge">3D · 단순 모델</span></div><div class="viewport" id="viewport"><div class="viewer-hint">드래그 회전 · 휠 확대 · 우클릭 이동 / 두 손가락 확대·이동</div></div>${controls()}<div class="legend">${Object.entries(types).map(([k,v])=>`<span><i style="background:${colors[k]}"></i>${v.split(' · ')[0]}</span>`).join('')}</div><div class="viewer-time">${icon('clock')}<label for="at-date">날짜 기준 보기</label><input id="at-date" type="date" value="${esc(at)}" max="${dateNow()}"><button class="small" data-action="date-now">현재</button><label class="check" style="margin-left:auto"><input id="show-closed" type="checkbox" ${status==='ALL'?'checked':''}>수리 · 종료 포함</label></div></section><div class="notice ${s.model==='CYLINDER'?'warn':''}" style="margin-top:13px">${s.model==='CYLINDER'?'원통형은 정확한 모델명이 미확정인 예시 형상입니다. 좌표·5mm 중복 후보·크기 측정은 참고용이며 실물 치수 확인이 필요합니다.':'치수 기반 단순 모델입니다. 사진을 주 증거로 확인하고, 3D는 부위와 방향을 찾는 용도로 사용하세요.'}</div><section class="card side-panel" style="margin-top:18px"><div class="section-title"><h3>센서 이력</h3><span class="kicker">${history.length}개 이벤트</span></div><div class="timeline">${timeline(history)}</div></section></div><aside class="card side-panel" id="sensor-panel"></aside></div><button class="primary floating-report" data-action="start-report">${icon('plus')}파손 신고</button>`);
 $('.viewer-layout').dataset.mobileTab='list';
 const historyPanel=$('.viewer-layout>div>section:last-child');historyPanel.id='sensor-history-panel';
 $('#sensor-panel').insertAdjacentHTML('beforebegin','<div class="mobile-tabs"><button class="active" data-action="mobile-tab" data-tab="list">파손 목록</button><button data-action="mobile-tab" data-tab="detail">상세</button><button data-action="mobile-tab" data-tab="history">이력</button></div>');
 viewer=initViewer($('#viewport'),s,{onPick:handlePick,onSelect:selectDamage});viewer?.setMarkers(damages,current.selected);damagePanel();if(current.selected)selectDamage(current.selected,false);
 $('#at-date').addEventListener('change',e=>setQuery({at:e.target.value}));$('#show-closed').addEventListener('change',e=>setQuery({status:e.target.checked?'ALL':'ACTIVE'}));
}
function timeline(rows){return rows.length?rows.map(e=>`<div class="timeline-item"><strong>${esc(events[e.kind]||e.kind)}</strong><small>${fmt(e.at)} · ${esc(e.actor)}</small><p>${esc(e.note||'')}${e.damage_id?' · '+esc(e.damage_id):''}</p></div>`).join(''):empty('아직 기록된 이력이 없습니다.','clock');}
function setQuery(values){const p=new URLSearchParams(location.search);Object.entries(values).forEach(([k,v])=>v?p.set(k,v):p.delete(k));go(appPath()+(p.size?'?'+p:''));}
function damagePanel(){if(!current||!$('#sensor-panel'))return;const ds=current.damages;$('#sensor-panel').innerHTML=`<div class="section-title"><h3>${current.at?'해당 날짜의 파손':'파손 목록'}</h3><span class="badge">${ds.length}건</span></div><p class="kicker">${current.at?current.at+' 기준':'승인된 파손만 표시합니다.'}</p><div class="damage-list">${ds.map((d,i)=>`<button class="damage-row ${d.id===current.selected?'selected':''}" data-action="damage" data-id="${d.id}"><span class="marker-number" style="--marker:${colors[d.type]}">${i+1}</span><div class="grow"><strong>${esc(types[d.type])} ${isNew(d)?'<span class="badge green" style="font-size:9px;padding:2px 4px">신규</span>':''}</strong><small>${esc(parts[d.part]||d.part)} · ${d.found_at}</small></div>${d.status!=='ACTIVE'?badge(d.status):icon('arrow')}</button>`).join('')||empty('아직 등록된 파손이 없습니다.<br>발견한 파손은 신고 버튼으로 기록하세요.','check')}</div><div id="damage-detail"></div>`;}
function isNew(d){const delta=(new Date(dateNow())-new Date(d.confirmed_at.slice(0,10)))/86400000;return delta>=0&&delta<=30;}
function photoStrip(photos){return photos?.length?`<div class="photos">${photos.map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener" title="사진 원본 보기"><img src="${esc(p.thumb)}" alt="${esc(p.name)}" loading="lazy"></a>`).join('')}</div>`:empty('첨부 사진 없음','camera');}
async function selectDamage(id,focus=true){if(!current||current.reporting)return;const d=current.damages.find(d=>d.id===id);if(!d)return;current.selected=id;if(matchMedia('(max-width:650px)').matches){document.querySelector('.viewer-layout').dataset.mobileTab='detail';document.querySelectorAll('.mobile-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab==='detail'));}const p=new URLSearchParams(location.search);p.set('damage',id);history.replaceState({},'',location.pathname+'?'+p);viewer?.setMarkers(current.damages,id);if(focus)viewer?.focus(d);damagePanel();const detail=await api('/damages/'+id);if(current?.selected!==id||current.reporting)return;$('#damage-detail').innerHTML=`<div class="panel-detail"><div class="row between"><h3>${esc(types[d.type])}</h3>${badge(d.status)}</div><p class="serial" style="margin-top:9px">${d.id}</p>${photoStrip(d.photos)}<dl class="data-pair"><dt>부위</dt><dd>${esc(parts[d.part]||d.part)}</dd><dt>최초 발견일</dt><dd>${d.found_at}</dd><dt>발생 추정 기간</dt><dd>${d.occurred_from?fmt(d.occurred_from)+' ~ '+d.found_at:'이전 점검 기록 없음'}</dd><dt>신고자</dt><dd>${esc(d.reporter_name)}</dd><dt>확정자</dt><dd>${esc(d.confirmed_by)}</dd>${d.size_mm?`<dt>${d.shape==='LINE'?'길이':'지름'}</dt><dd>${d.size_mm.toFixed(1)} mm</dd>`:''}</dl><p class="report-note">${esc(d.note)}</p>${isAdmin()&&d.status==='ACTIVE'&&!current.at?`<div class="row wrap" style="margin-top:18px"><button class="small" data-action="repair" data-id="${id}">수리 완료</button><button class="small" data-action="correct" data-id="${id}">정정 · 변화</button><button class="small" data-action="close-damage" data-id="${id}">종료</button></div>`:''}<div class="divider"></div><h3>이 파손의 전체 이력</h3><div class="timeline">${timeline(detail.events)}</div></div>`;}
function handlePick(p){if(!current)return;current.part=p.part;current.normal=p.normal;const shape=$('#geometry-shape')?.value||'POINT';if(['LINE','AREA'].includes(shape))current.points.push(p.point);else current.points=[p.point];viewer?.setSketch(current.points,current.normal,shape,Number($('#circle-size')?.value||3));updatePick();}
function updatePick(){const el=$('#picked-point');if(el)el.innerHTML=current.points.length?`${esc(parts[current.part]||current.part)} · ${current.points.length}개 점<br>${current.points.map(p=>p.map(n=>n.toFixed(1)).join(', ')).join('<br>')} mm`:'3D 센서 표면을 눌러 위치를 선택하세요.';const duplicate=$('#duplicate-notice');if(duplicate){const candidates=current.damages.filter(d=>d.part===current.part&&current.points.length&&Math.hypot(...current.points[0].map((x,i)=>x-d.points_mm[0][i]))<=5);duplicate.innerHTML=candidates.length?`<div class="notice warn">5mm 안에 기존 파손 ${candidates.length}건이 있습니다. 같은 파손의 재확인 또는 변화는 관리자가 기존 기록에 합칠 수 있습니다.</div><label class="check" style="margin-top:10px"><input type="checkbox" required>기존 파손 후보를 확인했습니다.</label>`:'';}}
function geometryFields(p={}){return `<div class="field-grid"><label>표시 모양<select id="geometry-shape" name="shape">${options({POINT:'점',LINE:'선 · 표면 두 점 이상',CIRCLE:'원 · 지름 지정',AREA:'영역 · 세 점 이상'},p.shape||'POINT')}</select></label><label>원 지름 (mm)<input id="circle-size" name="size_mm" type="number" min="0.1" max="500" step="0.1" value="${p.size_mm||3}"></label></div><button type="button" class="small" data-action="clear-points">위치 다시 찍기</button>`;}
function wireGeometry(){const shape=$('#geometry-shape');if(shape)shape.addEventListener('change',()=>{current.points=[];viewer?.setSketch([],current.normal);updatePick();});$('#circle-size')?.addEventListener('input',()=>viewer?.setSketch(current.points,current.normal,shape.value,Number($('#circle-size').value)));}
function selectedPayload(f){if(!current.points.length)throw new Error('3D 표면에서 위치를 선택하세요.');return {type:f.get('type'),found_at:f.get('found_at'),note:f.get('note')||'',part:current.part,points_mm:current.points,normal:current.normal,shape:f.get('shape')||'POINT',size_mm:Number(f.get('size_mm')||0)};}
function startReport(direct=false){if(!viewer)throw new Error('3D 뷰어를 사용할 수 없습니다.');if(current.at){setQuery({at:''});toast('현재 상태로 전환했습니다. 파손 신고를 다시 선택하세요.');return;}current.reporting=true;document.querySelector('.viewer-layout').dataset.mobileTab='report';current.points=[];current.normal=[0,1,0];viewer.setPicking(true);$('.floating-report')?.classList.add('hidden');$('#sensor-panel').innerHTML=`<div class="section-title"><h3>${direct?'관리자 직접 등록':'파손 신고'}</h3><button class="ghost small" data-action="cancel-report" aria-label="신고 닫기">${icon('close')}</button></div><div class="step-header"><span>1 위치</span><span>2 유형 · 사진</span><span>3 제출</span></div><form id="report-form"><div class="notice">${direct?'등록 즉시 모든 사용자에게 공개됩니다.':'신고는 관리자 승인 후 공개됩니다.'} 3D 표면을 눌러 파손 위치를 지정하세요.</div><div class="point-value" id="picked-point">위치를 선택하세요.</div>${direct?geometryFields():''}<div id="duplicate-notice"></div><label>파손 유형<select name="type">${options(types,'SCRATCH')}</select></label><label>발견일<input name="found_at" type="date" value="${dateNow()}" max="${dateNow()}" required></label><label>사진 · 2~5장 (장당 12MB 이하)<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label><div class="photo-guide"><svg viewBox="0 0 65 50"><rect x="2" y="3" width="26" height="37" rx="4" fill="none" stroke="currentColor"/><rect x="9" y="14" width="12" height="16" fill="none" stroke="currentColor"/><rect x="35" y="3" width="28" height="37" rx="4" fill="none" stroke="currentColor"/><path d="m39 13 10 14 9-8" stroke="currentColor" fill="none"/></svg><span>① 전체가 보이는 원거리 1장<br>② 파손이 크게 보이는 근접 1장<br>자·동전을 함께 찍으면 크기 비교가 쉽습니다.</span></div><label>메모 · 기타 유형은 필수<textarea name="note" maxlength="2000" placeholder="발견 상황과 파손 내용을 적어주세요."></textarea></label><button type="submit" class="primary">${direct?'파손 확정 등록':'검토 요청 제출'}</button>${!direct&&isAdmin()?'<button type="button" class="ghost small" data-action="direct-report">관리자 직접 등록으로 전환</button>':''}</form>`;wireGeometry();bindForm($('#report-form'),async f=>{const files=f.getAll('photos').filter(x=>x.size);if(files.length<2||files.length>5)throw new Error('전체·근접 사진을 2~5장 선택하세요.');const data=new FormData();data.set('sensor_id',current.sensor.id);data.set('payload',JSON.stringify(selectedPayload(f)));files.forEach(file=>data.append('photos',file));await api(direct?'/damages':'/reports',{method:'POST',body:data});toast(direct?'파손을 확정 등록했습니다.':'신고를 제출했습니다. 내 신고에서 진행 상황을 확인하세요.');await render();});}
async function reportsPage(adminMode,gen){const reports=await api('/reports'+(adminMode?'':'?mine=1'));if(gen!==routeGeneration)return;current={reports,adminMode};const active=reports.filter(r=>['SUBMITTED','IN_REVIEW'].includes(r.status));
 if(adminMode){shell('신고 검토',head('REVIEW INBOX','신고 검토','사진과 위치를 확인하고 파손 이력을 확정하세요.')+`<div class="review-layout"><aside class="review-list"><div class="section-title"><h3>검토 대기</h3><span class="badge amber">${active.length}건</span></div>${active.map(r=>`<button class="card review-card" data-action="review-report" data-id="${r.id}"><div class="row between"><strong>${r.robot_no||'예비'}호기 · ${slotNames[r.slot]||'센서'}</strong>${badge(r.status)}</div><p style="margin:12px 0 8px;font-size:13px">${esc(types[r.payload.type])}</p><p class="serial">${esc(r.reporter_name)} · ${fmt(r.created_at)}</p></button>`).join('')||empty('대기 중인 신고가 없습니다.','check')}</aside><section class="card review-content" id="review-content">${empty('왼쪽 신고를 선택하면 사진과 3D를 함께 검토할 수 있습니다.','review')}</section></div><div class="section-title" style="margin-top:30px"><h2>전체 신고 이력</h2></div>${reportsTable(reports,true)}`);if(active.length)await openReview(active[0].id);}
 else{shell('내 신고',head('MY REPORTS','내 신고','제출한 신고의 처리 상태를 확인하고 요청된 내용을 보완하세요.')+reportsTable([...reports].reverse(),false));}
}
function reportsTable(rows,adminMode){return `<div class="card table-wrap"><table><thead><tr><th>신고 번호</th><th>호기 · 센서</th><th>파손 유형</th><th>발견일</th><th>상태</th><th>처리 내용</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="mono">R-${String(r.id).padStart(4,'0')}</td><td><strong>${r.robot_no||'예비'}호기</strong><div class="sub">${esc(r.serial)}</div></td><td>${esc(types[r.payload.type])}</td><td>${r.payload.found_at}</td><td>${badge(r.status)}</td><td>${esc(r.reason||'—')}</td><td><button class="small" data-action="${adminMode&&['SUBMITTED','IN_REVIEW'].includes(r.status)?'review-report':'report-detail'}" data-id="${r.id}">상세</button>${r.status==='NEED_INFO'&&r.reporter_id===user.id?` <button class="small primary" data-action="reply" data-id="${r.id}">보완</button>`:''}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('아직 제출한 신고가 없습니다.','file')}</div>`;}
async function openReview(id){if(viewer){viewer.dispose();viewer=null;}const r=current.reports.find(r=>r.id===Number(id));if(!r)return;if(r.status==='SUBMITTED'){await api(`/reports/${id}/review`,{method:'POST',body:{}});r.status='IN_REVIEW';}const[s,damages]=await Promise.all([api('/sensors/'+r.sensor_id),api('/sensors/'+r.sensor_id+'/damages')]);if(!$('#review-content'))return;current={...current,review:r,sensor:s,damages,points:r.payload.points_mm.map(p=>[...p]),normal:r.payload.normal,part:r.payload.part};$$('.review-card').forEach(b=>b.classList.toggle('selected',b.dataset.id===String(id)));const p=r.payload;
 $('#review-content').innerHTML=`<div class="section-title"><div><h2>신고 R-${String(id).padStart(4,'0')}</h2><p class="subtitle">${esc(r.reporter_name)} · ${fmt(r.created_at)}</p></div>${badge(r.status)}</div><div class="review-workspace"><div><div id="review-viewport" class="viewport review-viewport card"></div>${controls()}<div class="notice">표면을 클릭해 확정 위치를 조정하세요. 선·영역은 모양 선택 후 표면을 순서대로 클릭합니다.</div>${photoStrip(r.photos)}<p class="report-note">신고 메모: ${esc(p.note||'없음')}</p></div><form id="review-form" class="review-form"><label>확정 유형<select name="type">${options(types,p.type)}</select></label>${geometryFields(p)}<div class="point-value" id="picked-point"></div><label>발견일<input type="date" name="found_at" value="${p.found_at}" max="${dateNow()}" required></label><label>확정 메모<textarea name="note">${esc(p.note)}</textarea></label><label>기존 파손에 합치기<select name="merge_id"><option value="">새 파손으로 확정</option>${damages.map(d=>`<option value="${d.id}">${d.id} · ${types[d.type]}${d.part===p.part&&Math.hypot(...d.points_mm[0].map((x,i)=>x-p.points_mm[0][i]))<=5?' · 5mm 이내':''}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="change">병합 시 새 범위로 변화 기록</label><button class="primary" type="submit">${icon('check')}승인 · 확정</button><div class="row"><button type="button" class="grow" data-action="request-info" data-id="${id}">보완 요청</button><button type="button" class="danger grow" data-action="reject" data-id="${id}">반려</button></div></form></div>`;
 viewer=initViewer($('#review-viewport'),s,{onPick:handlePick});viewer?.setPicking(true);viewer?.setMarkers(damages);viewer?.setSketch(current.points,current.normal,p.shape,p.size_mm||3);viewer?.focus(p);updatePick();wireGeometry();bindForm($('#review-form'),async f=>{await api(`/reports/${id}/approve`,{method:'POST',body:{payload:selectedPayload(f),merge_id:f.get('merge_id'),change:!!f.get('change'),reason:f.get('note')||'기존 파손 재확인'}});toast('승인했습니다. 파손 이력에 반영되었습니다.');await render();});
}
async function managePage(gen){const[robots,spares]=await Promise.all([api('/robots?status=ALL'),api('/sensors')]);if(gen!==routeGeneration)return;current={robots,spares};shell('호기 · 센서 관리',head('ASSET MANAGEMENT','호기 · 센서 관리','실물 시리얼과 장착 이력을 연결해 관리하세요.',`<button data-action="csv">${icon('download')}CSV 등록</button><button data-action="add-robot" class="primary">${icon('plus')}호기 등록</button>`)+`<div class="notice" style="margin-bottom:20px">초기 120개 센서는 실물 시리얼이 미확인인 임시 기록입니다. 실물 시리얼 등록은 기존 이력을 유지하며, 센서 교체는 별도의 장착 이력을 만듭니다.</div><div class="card table-wrap"><table><thead><tr><th>호기</th><th>사이트</th><th>라이다</th><th>상태</th><th>시리얼 확인</th><th>관리</th></tr></thead><tbody>${robots.map(r=>`<tr><td><a href="/robot/${r.no}"><strong>${String(r.no).padStart(2,'0')}호기</strong></a></td><td>${esc(r.site)}</td><td>${r.shape==='DOME'?'반구형':'원통형'}</td><td><span class="badge ${r.status==='ACTIVE'?'green':''}">${r.status==='ACTIVE'?'운영':'폐기'}</span></td><td>${r.verified}/4</td><td><button class="small" data-action="asset-detail" data-no="${r.no}">센서 관리</button> <button class="small" data-action="edit-robot" data-no="${r.no}">설정</button></td></tr>`).join('')}</tbody></table></div><div class="section-title" style="margin-top:30px"><h2>예비 센서</h2><span class="badge">${spares.length}개</span></div><div class="card table-wrap"><table><thead><tr><th>시리얼</th><th>모델</th><th>이력</th></tr></thead><tbody>${spares.map(s=>`<tr><td>${esc(s.serial)}</td><td>${esc(s.model)}</td><td><button class="small" data-action="sensor-history" data-id="${s.id}">파손 · 장착 이력</button></td></tr>`).join('')}</tbody></table>${spares.length?'':empty('회수된 예비 센서가 없습니다.')}</div>`);}
async function usersPage(gen){const[users,audit,models]=await Promise.all([api('/users'),api('/audit'),api('/models')]);if(gen!==routeGeneration)return;current={users,models};shell('계정 관리',head('SYSTEM ADMINISTRATION','계정 및 시스템 관리','개인별 계정과 역할, 모델 파일, 변경 기록을 관리하세요.',`<button data-action="add-user" class="primary">${icon('plus')}계정 발급</button>`)+`<div class="card table-wrap"><table><thead><tr><th>사용자</th><th>아이디</th><th>소속</th><th>권한</th><th>상태</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td class="mono">${esc(u.username)}</td><td>${esc(u.department||'—')}</td><td>${roles[u.role]}</td><td><span class="badge ${u.active?'green':''}">${u.active?'사용 중':'사용 중지'}</span></td><td>${u.id!==user.id?`<button class="small" data-action="edit-user" data-id="${u.id}">권한 · 사용 설정</button>`:'현재 계정'}</td></tr>`).join('')}</tbody></table></div><div class="section-title" style="margin-top:32px"><h2>센서 3D 모델</h2><span class="kicker">GLB · mm · +Y 위 · +Z 앞</span></div><div class="card table-wrap"><table><thead><tr><th>모델</th><th>현재 파일</th><th></th></tr></thead><tbody>${models.map(m=>`<tr><td>${esc(m.label)}</td><td>${m.file?'등록된 GLB · 버전 '+m.revision:'내장 단순 모델'}</td><td><button class="small" data-action="upload-model" data-id="${m.id}">모델 교체</button></td></tr>`).join('')}</tbody></table></div><div class="section-title" style="margin-top:32px"><h2>변경 기록</h2><span class="kicker">최근 500개 · 한국 시간</span></div><div class="card table-wrap"><table><thead><tr><th>일시</th><th>처리자</th><th>행위</th><th>대상</th><th>내용</th></tr></thead><tbody>${audit.map(a=>`<tr><td style="white-space:nowrap">${fmt(a.at)}</td><td>${esc(a.actor)}</td><td class="mono">${esc(a.action)}</td><td>${esc(a.target)}</td><td><details><summary>내용 보기</summary><p class="report-note">${esc(a.detail)}</p></details></td></tr>`).join('')}</tbody></table></div>`);}

const actions={
 'mobile-tab':b=>{const tab=b.dataset.tab;$('.viewer-layout').dataset.mobileTab=tab;$$('.mobile-tabs button').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));if(tab==='detail'&&!current.selected)toast('파손 목록에서 항목을 먼저 선택하세요.');},
 'logout':async()=>{await api('/auth/logout',{method:'POST',body:{}});user=null;csrf='';go('/login');},
 'reload':()=>render(),
 'demo-login':b=>{const f=$('#login-form');f.username.value=b.dataset.u;f.password.value=b.dataset.p;f.requestSubmit();},
 'demo-reset':()=>modal('데모 초기화',`<form><div class="notice warn">이 브라우저에 저장된 웹 데모 데이터(신고·사진·계정 변경)를 모두 지우고 예시 데이터로 다시 시작합니다.</div><button type="submit" class="danger">초기화</button></form>`,async()=>{await fetch(BASE+'/__demo/reset',{method:'POST'});user=null;location.replace(BASE+'/');}),
 'password':()=>modal('비밀번호 변경',`<form>${passwordFields()}</form>`,changePassword),
 'close-modal':()=>$('#modal').close(),
 'filter-status':b=>{const p=new URLSearchParams(location.search);p.set('status',b.dataset.status);go('/?'+p);},
 'view':b=>viewer?.setView(b.dataset.view),
 'date-now':()=>setQuery({at:''}),
 'damage':b=>selectDamage(b.dataset.id),
 'start-report':()=>startReport(),
 'direct-report':()=>startReport(true),
 'cancel-report':()=>render(),
 'clear-points':()=>{current.points=[];viewer?.setSketch([],current.normal);updatePick();},
 'share':async()=>{try{await navigator.clipboard.writeText(location.href);toast('현재 센서·파손·날짜의 주소를 복사했습니다.');}catch{modal('공유 주소',`<label>주소를 복사하세요<input readonly value="${esc(location.href)}"></label>`);}},
 'qr':b=>modal(`${b.dataset.no}호기 QR 코드`,`<img class="qr" alt="${b.dataset.no}호기 접속 QR" src="/api/robots/${b.dataset.no}/qr"><p class="subtitle" style="text-align:center">${DEMO?'웹 데모의 QR은 이 데모 주소로 연결됩니다.<br>데이터는 브라우저마다 따로라 다른 기기에서는 예시 데이터로 보입니다.':'인쇄 후 로봇에 부착하세요.<br>휴대폰 접속용 서버 주소는 PUBLIC_URL로 설정합니다.'}</p><a href="/api/robots/${b.dataset.no}/qr" download="robot-${b.dataset.no}-qr.png"><button style="width:100%;margin-top:15px">${icon('download')}QR 이미지 저장</button></a>`),
 'inspect':()=>modal('점검 완료 기록',`<form><div class="notice">현재 센서를 확인했고, 새로 발견한 파손이 없음을 기록합니다. 이전 파손을 정상으로 바꾸지는 않습니다.</div><label>점검 메모<textarea name="note" placeholder="점검 상황을 입력하세요."></textarea></label><button class="primary" type="submit">신규 파손 없음 · 점검 완료</button></form>`,async f=>{await api(`/sensors/${current.sensor.id}/inspections`,{method:'POST',body:{note:f.get('note')}});toast('점검 기록을 저장했습니다.');await render();}),
 'review-report':b=>openReview(Number(b.dataset.id)),
 'request-info':b=>reviewDecision(b.dataset.id,'request-info','보완 요청'),
 'reject':b=>reviewDecision(b.dataset.id,'reject','신고 반려'),
 'report-detail':b=>{const r=current.reports.find(r=>r.id===Number(b.dataset.id));modal('신고 상세',`<div class="row between"><strong>R-${r.id} · ${esc(types[r.payload.type])}</strong>${badge(r.status)}</div>${photoStrip(r.photos)}<dl class="data-pair"><dt>발견일</dt><dd>${r.payload.found_at}</dd><dt>신고자</dt><dd>${esc(r.reporter_name)}</dd><dt>처리 사유</dt><dd>${esc(r.reason||'—')}</dd><dt>연결된 파손</dt><dd>${esc(r.damage_id||'—')}</dd></dl><p class="report-note">${esc(r.payload.note||'메모 없음')}</p>`);},
 'reply':b=>modal('신고 보완',`<form><label>보완 내용<textarea name="note" required></textarea></label><label>추가 사진 · 최대 5장<input type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple></label><button class="primary" type="submit">보완 제출</button></form>`,async f=>{await api(`/reports/${b.dataset.id}/reply`,{method:'POST',body:cleanFiles(f)});toast('보완 내용을 제출했습니다.');await render();}),
 'repair':b=>damageState(b.dataset.id,'REPAIRED','수리 완료',true),
 'close-damage':b=>damageState(b.dataset.id,'CLOSED','파손 종료',false),
 'correct':b=>editDamage(b.dataset.id),
 'add-robot':async()=>{const rows=current.robots||await api('/robots?status=ALL'),no=Math.max(0,...rows.map(r=>r.no))+1;modal('새 호기 등록',`<form><label>호기번호<input name="no" type="number" min="1" max="99999" value="${no}" required></label><label>사이트<input name="site" placeholder="고객사 · 현장" value="미지정" required></label><label>라이다 형상<select name="shape"><option value="">호기번호로 자동 선택 (16 이하 원통형)</option>${options({CYLINDER:'원통형',DOME:'반구형'})}</select></label><div class="notice">등록 후 센서 관리에서 실물 센서를 장착하세요.</div><button type="submit" class="primary">등록</button></form>`,async f=>{const d=Object.fromEntries(f);await api('/robots',{method:'POST',body:d});toast('호기를 등록했습니다.');await render();});},
 'edit-robot':async b=>{const r=await api('/robots/'+b.dataset.no);modal(`${r.no}호기 설정`,`<form><label>사이트<input name="site" value="${esc(r.site)}" required></label><label>라이다 형상<select name="shape">${options({CYLINDER:'원통형',DOME:'반구형'},r.shape)}</select></label><div class="notice">파손 이력이 있는 센서의 형상 변경은 제한됩니다. 실제 센서가 바뀌면 교체 기능을 사용하세요.</div><button type="submit" class="primary">설정 저장</button>${r.status==='ACTIVE'?`<button class="danger" type="button" data-action="dispose" data-no="${r.no}">호기 폐기 처리</button>`:''}${user.role==='SYSADMIN'&&!r.sensors.length?`<button class="danger" type="button" data-action="delete-robot" data-no="${r.no}">잘못 등록한 빈 호기 영구 삭제</button>`:''}</form>`,async f=>{await api('/robots/'+r.no,{method:'PATCH',body:Object.fromEntries(f)});toast('호기 설정을 저장했습니다.');await render();});},
 'asset-detail':b=>assetDetail(b.dataset.no),
 'identify':b=>modal('실물 시리얼 등록',`<form><label>실물 시리얼<input name="serial" required placeholder="제품 라벨의 고유 시리얼"></label><label>장착 위치<input name="position" value="미확인" required></label><div class="notice">임시 센서의 이력을 그대로 유지합니다. 실물이 교체된 경우 센서 교체를 사용하세요.</div><button class="primary" type="submit">확인 · 등록</button></form>`,async f=>{await api('/sensors/'+b.dataset.id,{method:'PATCH',body:Object.fromEntries(f)});toast('실물 시리얼을 등록했습니다.');await render();}),
 'mount':b=>mountForm(b.dataset.no,b.dataset.slot),
 'dispose':b=>disposeForm(b.dataset.no),
 'sensor-history':async b=>{const[s,history,ds]=await Promise.all([api('/sensors/'+b.dataset.id),api('/sensors/'+b.dataset.id+'/history'),api('/sensors/'+b.dataset.id+'/damages?status=ALL')]);modal('센서 파손 · 장착 이력',`<h3>${esc(s.serial)}</h3><p class="subtitle">${s.label} · ${s.status}</p>${ds.map(d=>`<div class="divider"></div><div class="row between"><strong>${esc(types[d.type])}</strong>${badge(d.status)}</div><p class="subtitle">${d.found_at} · ${esc(parts[d.part]||d.part)} · ${d.id}</p>${photoStrip(d.photos)}`).join('')}<div class="divider"></div><div class="timeline">${timeline(history)}</div>`);},
 'csv':()=>modal('센서 시리얼 CSV 등록',`<form><div class="notice">헤더: robot_no,slot,serial,position<br>슬롯: LIDAR_1, LIDAR_2, CAM_1, CAM_2<br>전체 행을 검증한 뒤 한 번에 저장합니다. 실물 교체용이 아닙니다.</div><a href="/sample-sensors.csv" download class="link-button">CSV 양식 다운로드</a><label>UTF-8 CSV 파일<input name="file" type="file" accept=".csv" required></label><button type="submit" class="primary">일괄 등록</button></form>`,async f=>{const r=await api('/robots/import-csv',{method:'POST',body:f});toast(`${r.count}개 시리얼을 등록했습니다.`);await render();}),
 'add-user':()=>modal('계정 발급',`<form><div class="field-grid"><label>아이디<input name="username" pattern="[a-zA-Z0-9._-]{3,60}" required></label><label>이름<input name="name" required></label></div><label>소속<input name="department"></label><label>권한<select name="role">${options(roles,'FIELD')}</select></label><label>임시 비밀번호 · 12자 이상<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><div class="notice">계정 정보는 담당자에게 별도로 전달하세요. 첫 로그인에서 비밀번호를 변경합니다.</div><button type="submit" class="primary">계정 발급</button></form>`,async f=>{await api('/users',{method:'POST',body:Object.fromEntries(f)});toast('계정을 발급했습니다.');await render();}),
 'edit-user':b=>{const u=current.users.find(x=>x.id===Number(b.dataset.id));modal(`${u.name} 계정 설정`,`<form><label>권한<select name="role">${options(roles,u.role)}</select></label><label>사용 상태<select name="active">${options({'1':'사용 중','0':'사용 중지'},String(u.active))}</select></label><div class="notice">설정 변경 시 해당 사용자의 기존 로그인 세션은 종료됩니다.</div><button type="submit" class="primary">저장</button></form>`,async f=>{await api('/users/'+u.id,{method:'PATCH',body:{role:f.get('role'),active:Number(f.get('active'))}});toast('계정 설정을 저장했습니다.');await render();});},
 'upload-model':b=>modal('센서 GLB 모델 교체',`<form><div class="notice warn">좌표는 mm, 원점은 센서 중심, +Y는 위, +Z는 앞입니다. 부위별 메시 이름을 유지하세요. 기존 마커 좌표는 변환되지 않습니다. 교체 전 백업 후 정합성을 확인하세요.</div><label>GLB 2.0 파일 · 2MB 이하<input type="file" name="file" accept=".glb" required></label><label class="check"><input type="checkbox" required>치수·좌표계·부위 이름을 확인했습니다.</label><button type="submit" class="primary">모델 교체</button></form>`,async f=>{await api('/models/'+b.dataset.id,{method:'POST',body:f});toast('3D 모델을 교체했습니다.');await render();}),
 'delete-robot':b=>modal('빈 호기 영구 삭제',`<form><div class="notice warn">장착·신고 이력이 없는 오등록 호기만 삭제할 수 있습니다. 삭제 후 복구할 수 없습니다.</div><label>오등록 사유<textarea name="reason" required></textarea></label><button type="submit" class="danger">${b.dataset.no}호기 영구 삭제</button></form>`,async f=>{await api('/robots/'+b.dataset.no,{method:'DELETE',body:Object.fromEntries(f)});toast('빈 호기를 삭제했습니다.');await render();})
};
function cleanFiles(f){const out=new FormData();for(const[k,v]of f)if(!(v instanceof File)||v.size)out.append(k,v);return out;}
function reviewDecision(id,action,title){modal(title,`<form><label>사유 · 필수<textarea name="reason" required></textarea></label><button type="submit" class="${action==='reject'?'danger':'primary'}">${title}</button></form>`,async f=>{await api(`/reports/${id}/${action}`,{method:'POST',body:{reason:f.get('reason')}});toast(title+'을 저장했습니다.');await render();});}
function damageState(id,action,title,photoRequired){modal(title,`<form><label>처리 사유 · 필수<textarea name="reason" required></textarea></label>${photoRequired?'<label>수리 후 사진 · 1~5장<input type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple required></label>':''}<div class="notice">이전 기록은 보존되며, 과거 날짜 보기에서 확인할 수 있습니다.</div><button type="submit" class="primary">${title} 기록</button></form>`,async f=>{f.set('action',action);await api('/damages/'+id,{method:'PATCH',body:f});toast(title+'를 기록했습니다.');await render();});}
function editDamage(id){const d=current.damages.find(d=>d.id===id);current.reporting=true;document.querySelector('.viewer-layout').dataset.mobileTab='report';current.points=d.points_mm.map(p=>[...p]);current.normal=[...d.normal];current.part=d.part;viewer?.setPicking(true);viewer?.setSketch(current.points,current.normal,d.shape,d.size_mm||3);$('#sensor-panel').innerHTML=`<div class="section-title"><h3>파손 정정 · 변화</h3><button class="small ghost" data-action="cancel-report">취소</button></div><form id="edit-damage-form"><label>변경 종류<select name="action"><option value="CORRECTED">잘못 기록된 내용 정정</option><option value="CHANGED">파손이 커짐 · 변화 기록</option></select></label><label>유형<select name="type">${options(types,d.type)}</select></label>${geometryFields(d)}<div id="picked-point" class="point-value"></div><label>발견일<input type="date" name="found_at" value="${d.found_at}" max="${dateNow()}" required></label><label>변경 후 메모<textarea name="note">${esc(d.note)}</textarea></label><label>변경 사유<textarea name="reason" required></textarea></label><label>새 사진 · 변화 기록 시 필수<input type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple></label><button type="submit" class="primary">변경 기록 저장</button></form>`;wireGeometry();updatePick();bindForm($('#edit-damage-form'),async f=>{const out=cleanFiles(f);out.set('payload',JSON.stringify(selectedPayload(f)));await api('/damages/'+id,{method:'PATCH',body:out});toast('변경 전후 내용을 이력에 저장했습니다.');await render();});}
async function assetDetail(no){const r=await api('/robots/'+no);let old=[];if(r.status==='DISPOSED'){const h=await api('/admin/disposed-sensors/'+no).catch(()=>[]);old=h;}modal(`${no}호기 센서 관리`,`<div class="stack">${Object.entries(slotNames).map(([slot,label])=>{const s=r.sensors.find(s=>s.slot===slot);return `<div class="card" style="padding:16px"><div class="row between"><h3>${label}</h3><span class="badge">${esc(s?.position||'미장착')}</span></div><p class="serial" style="margin:12px 0">${s?esc(s.verified?s.serial:'시리얼 미확인 · 임시 ID '+s.id):'현재 장착 없음'}</p><div class="row wrap">${s&&!s.verified?`<button class="small" data-action="identify" data-id="${s.id}">시리얼 등록</button>`:''}${s?`<button class="small" data-action="sensor-history" data-id="${s.id}">이력</button>`:''}${r.status==='ACTIVE'?`<button class="small" data-action="mount" data-no="${no}" data-slot="${slot}">${s?'센서 교체':'센서 장착'}</button>`:''}</div></div>`;}).join('')}${old.length?`<h3>폐기 전 장착 센서</h3>${old.map(s=>`<button class="small" data-action="sensor-history" data-id="${s.id}">${slotNames[s.slot]} · ${esc(s.serial)}</button>`).join('')}`:''}</div>`);}
async function mountForm(no,slot){const spares=await api('/sensors');modal(`${no}호기 · ${slotNames[slot]} 장착 / 교체`,`<form><label>장착할 예비 센서<select name="sensor_id"><option value="">새 실물 센서 등록</option>${spares.map(s=>`<option value="${s.id}">${esc(s.serial)} (${s.model})</option>`).join('')}</select></label><label>새 실물 시리얼 (예비 선택 시 비움)<input name="serial"></label><label>장착 위치<input name="position" placeholder="예: 전방 상단" value="미확인"></label><label>기존 센서 처리<select name="old_status"><option value="SPARE">예비로 회수 · 파손 이력 유지</option><option value="DISPOSED">폐기 · 현존 파손 종료</option></select></label><div class="notice">예비 센서를 다른 호기에 달아도 그 센서의 기존 파손이 함께 표시됩니다.</div><button class="primary" type="submit">장착 · 교체 기록</button></form>`,async f=>{await api('/robots/'+no+'/mounts',{method:'POST',body:{...Object.fromEntries(f),slot}});toast('센서 장착 이력을 저장했습니다.');await render();});}
async function disposeForm(no){const r=await api('/robots/'+no);modal(`${no}호기 폐기 처리`,`<form><label>폐기일<input type="date" name="date" max="${dateNow()}" value="${dateNow()}" required></label><label>폐기 사유<textarea name="reason" required></textarea></label>${r.sensors.map(s=>`<label>${slotNames[s.slot]} · ${esc(s.verified?s.serial:'미확인 ID '+s.id)}<select name="sensor_${s.id}"><option value="SPARE">예비로 회수</option><option value="DISPOSED">함께 폐기</option></select></label>`).join('')}<div class="notice warn">폐기 후 운영 목록에서 제외됩니다. 회수 센서의 파손 이력은 유지되고, 함께 폐기한 센서의 현존 파손은 종료됩니다.</div><button type="submit" class="danger">폐기 확정</button></form>`,async f=>{await api('/robots/'+no+'/dispose',{method:'POST',body:{date:f.get('date'),reason:f.get('reason'),sensors:Object.fromEntries(r.sensors.map(s=>[s.id,f.get('sensor_'+s.id)]))}});toast('폐기 처리했습니다.');await render();});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-go],a');if(!b)return;if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.action){e.preventDefault();try{await actions[b.dataset.action]?.(b);}catch(err){toast(err.message);}return;}const href=appPath(b.getAttribute('href')||'');if(b.tagName==='A'&&href.startsWith('/')&&!b.hasAttribute('download')&&!b.hasAttribute('data-external')&&!b.target&&!href.startsWith('/api/')&&!href.startsWith('/files/')){e.preventDefault();go(href);}});
document.addEventListener('model-error',()=>toast('등록된 GLB를 불러오지 못해 내장 모델을 표시합니다.'));
window.addEventListener('popstate',render);
pollTimer=setInterval(async()=>{if(!user||user.must_change||document.hidden)return;try{summary=await api('/summary');$$('[data-pending]').forEach(e=>e.textContent=summary.pending);}catch{}},30000);
await render();
